<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Interface Router - NetMonitor</title><link rel="stylesheet" href="../assets/css/variables.css"><link rel="stylesheet" href="../assets/css/common.css"><link rel="stylesheet" href="../assets/css/theme.css?v=1"><link rel="stylesheet" href="../assets/css/router.css"><style>
.page{margin-left:220px;padding:32px}.head{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:22px}.title{font-size:28px;font-weight:700}.sub{color:#66758d;margin-top:5px}.actions{display:flex;gap:10px}.btn{border:1px solid #d7e0ec;background:#fff;border-radius:8px;padding:10px 14px;font-weight:600;cursor:pointer}.btn.primary{background:#087cff;color:#fff;border-color:#087cff}.card{background:#fff;border:1px solid #dce4ef;border-radius:14px;box-shadow:0 5px 20px #00000008;overflow:hidden}.bar{padding:16px 20px;border-bottom:1px solid #e4e9f0;display:flex;justify-content:space-between}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:14px 16px;text-align:left;border-bottom:1px solid #edf1f6;font-size:13px}th{font-size:11px;text-transform:uppercase;letter-spacing:.5px;color:#61718a;background:#f7f9fc}.name{font-weight:700}.badge{display:inline-block;padding:5px 9px;border-radius:99px;font-size:11px;font-weight:700}.up{background:#dff6e9;color:#08774e}.down{background:#fde5e5;color:#b42318}.muted{color:#718096}.metric{font-variant-numeric:tabular-nums}.notice{padding:14px 20px;color:#66758d}.spinner{display:inline-block;width:14px;height:14px;border:2px solid #d5deea;border-top-color:#087cff;border-radius:50%;animation:spin .7s linear infinite;vertical-align:-2px}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:800px){.page{margin-left:0;padding:20px}.head{align-items:flex-start;flex-direction:column}}
</style></head><body><main class="page"><div class="head"><div><div class="title">Interface Router</div><div class="sub">Monitoring interface MikroTik secara realtime.</div></div><div class="actions"><button class="btn primary" id="refresh"><span>↻</span> Refresh</button></div></div><div class="card"><div class="bar"><strong id="router">Router</strong><span class="muted" id="updated">Belum diperbarui</span></div><div class="table-wrap"><table><thead><tr><th>Interface</th><th>Tipe</th><th>Status</th><th>MTU</th><th>MAC Address</th><th>RX</th><th>TX</th></tr></thead><tbody id="rows"><tr><td colspan="7" class="notice"><span class="spinner"></span> Mengambil data interface...</td></tr></tbody></table></div></div></main><script>
const rows=document.getElementById('rows'),router=document.getElementById('router'),updated=document.getElementById('updated'),refresh=document.getElementById('refresh');const fmt=n=>{n=Number(n)||0;if(n<1024)return n.toFixed(0)+' B';if(n<1048576)return (n/1024).toFixed(1)+' KB';if(n<1073741824)return (n/1048576).toFixed(1)+' MB';return (n/1073741824).toFixed(2)+' GB'};async function load(){refresh.disabled=true;refresh.innerHTML='<span class="spinner"></span> Memuat';try{const r=await fetch('../api/router_interfaces.php?nocache='+Date.now(),{cache:'no-store'});const d=await r.json();if(d.status!=='online')throw new Error(d.message||'Router offline');router.textContent=d.router||'Router';rows.innerHTML=(d.interfaces||[]).map(x=>`<tr><td class="name">${esc(x.name)}</td><td>${esc(x.type)}</td><td><span class="badge ${x.running&&!x.disabled?'up':'down'}">${x.disabled?'DISABLED':x.running?'RUNNING':'DOWN'}</span></td><td>${esc(x.mtu)}</td><td class="muted">${esc(x.mac)}</td><td class="metric">${fmt(x.rx_bytes)}</td><td class="metric">${fmt(x.tx_bytes)}</td></tr>`).join('')||'<tr><td colspan="7" class="notice">Tidak ada interface.</td></tr>'}catch(e){rows.innerHTML='<tr><td colspan="7" class="notice">Gagal mengambil data: '+esc(e.message)+'</td></tr>'}finally{updated.textContent='Update '+new Date().toLocaleTimeString('id-ID');refresh.disabled=false;refresh.innerHTML='↻ Refresh'}}function esc(v){return String(v??'-').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}refresh.addEventListener('click',load);load();setInterval(load,10000);
</script><script src="../assets/js/app.js?v=6"></script></body></html>